import { createHash, randomBytes } from 'node:crypto'

import { and, eq, isNull, sql } from 'drizzle-orm'
import { z } from 'zod'

import type { db as Database } from '#/db'
import { devices, enrollmentTokens } from '#/db/schema'
import { encryptSecret } from '#/lib/crypto'

export const EnrollmentRegistrationSchema = z.object({
  rustdeskId: z
    .string()
    .trim()
    .regex(/^\d{6,12}$/, 'RustDesk ID must contain 6 to 12 digits.'),
  alias: z.string().trim().min(1).max(120),
  hostname: z.string().trim().max(255).optional().default(''),
  os: z.string().trim().max(120).optional().default(''),
  rustdeskVersion: z.string().trim().max(80).optional().default(''),
  password: z.string().min(8).max(256),
})

export type EnrollmentRegistration = z.infer<
  typeof EnrollmentRegistrationSchema
>

export class EnrollmentError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
  ) {
    super(message)
    this.name = 'EnrollmentError'
  }
}

/** Create a high-entropy bearer token. The plaintext is returned only once. */
export function generateEnrollmentToken(): string {
  return `rdb_${randomBytes(32).toString('base64url')}`
}

/** Stable lookup digest; the bearer token itself is never persisted. */
export function hashEnrollmentToken(token: string): string {
  return createHash('sha256').update(token, 'utf8').digest('hex')
}

export function enrollmentTokenPrefix(token: string): string {
  return `${token.slice(0, 12)}…`
}

export interface EnrollmentResult {
  deviceId: string
  rustdeskId: string
  created: boolean
}

/**
 * Authenticate an enrollment bearer and atomically register its device.
 *
 * Single-use tokens may create exactly one device. A replay for that same
 * RustDesk ID is idempotent, but never overwrites its stored password.
 * Permanent tokens upsert only devices previously enrolled by that token.
 */
export async function registerEnrolledDevice(
  db: typeof Database,
  rawToken: string,
  registration: EnrollmentRegistration,
): Promise<EnrollmentResult> {
  const tokenHash = hashEnrollmentToken(rawToken)
  const now = new Date()

  return db.transaction(async (tx) => {
    const [token] = await tx
      .select()
      .from(enrollmentTokens)
      .where(eq(enrollmentTokens.tokenHash, tokenHash))
      .limit(1)

    if (!token || token.revokedAt) {
      throw new EnrollmentError(401, 'invalid_token', 'Invalid or revoked enrollment token.')
    }

    const [existing] = await tx
      .select({ id: devices.id, rustdeskId: devices.rustdeskId })
      .from(devices)
      .where(
        and(
          eq(devices.enrollmentTokenId, token.id),
          eq(devices.rustdeskId, registration.rustdeskId),
        ),
      )
      .limit(1)

    if (token.kind === 'single' && existing) {
      await tx
        .update(enrollmentTokens)
        .set({ lastUsedAt: now })
        .where(eq(enrollmentTokens.id, token.id))
      return {
        deviceId: existing.id,
        rustdeskId: existing.rustdeskId,
        created: false,
      }
    }

    if (token.kind === 'single') {
      const [claimed] = await tx
        .update(enrollmentTokens)
        .set({
          useCount: sql`${enrollmentTokens.useCount} + 1`,
          usedAt: now,
          lastUsedAt: now,
        })
        .where(
          and(
            eq(enrollmentTokens.id, token.id),
            eq(enrollmentTokens.useCount, 0),
            isNull(enrollmentTokens.revokedAt),
          ),
        )
        .returning({ id: enrollmentTokens.id })

      if (!claimed) {
        throw new EnrollmentError(
          409,
          'token_used',
          'This single-use token has already enrolled a device.',
        )
      }
    } else {
      await tx
        .update(enrollmentTokens)
        .set({
          useCount: sql`${enrollmentTokens.useCount} + 1`,
          lastUsedAt: now,
        })
        .where(
          and(
            eq(enrollmentTokens.id, token.id),
            isNull(enrollmentTokens.revokedAt),
          ),
        )
    }

    const passwordCipher = encryptSecret(registration.password)
    const values = {
      rustdeskId: registration.rustdeskId,
      alias: registration.alias,
      customer: token.customer,
      osKey: registration.os || null,
      tags: token.tags,
      status: 'offline',
      lastSeen: now,
      passwordCipher,
      enrollmentTokenId: token.id,
      createdBy: token.createdBy,
      updatedAt: now,
    }

    const [device] = await tx
      .insert(devices)
      .values(values)
      .onConflictDoUpdate({
        target: [devices.enrollmentTokenId, devices.rustdeskId],
        set: {
          alias: values.alias,
          customer: values.customer,
          osKey: values.osKey,
          tags: values.tags,
          lastSeen: values.lastSeen,
          passwordCipher: values.passwordCipher,
          updatedAt: values.updatedAt,
        },
      })
      .returning({ id: devices.id, rustdeskId: devices.rustdeskId })

    return {
      deviceId: device.id,
      rustdeskId: device.rustdeskId,
      created: !existing,
    }
  })
}

