import '#/polyfill'

import { createFileRoute } from '@tanstack/react-router'

import { db } from '#/db'
import {
  EnrollmentError,
  EnrollmentRegistrationSchema,
  registerEnrolledDevice,
} from '#/lib/enrollment'

const MAX_BODY_BYTES = 16 * 1024

function json(body: unknown, status = 200) {
  return Response.json(body, {
    status,
    headers: {
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
    },
  })
}

async function parseInput(request: Request): Promise<unknown> {
  const declaredLength = Number(request.headers.get('content-length') ?? 0)
  if (declaredLength > MAX_BODY_BYTES) {
    throw new EnrollmentError(413, 'payload_too_large', 'Enrollment payload is too large.')
  }

  const body = await request.text()
  if (Buffer.byteLength(body, 'utf8') > MAX_BODY_BYTES) {
    throw new EnrollmentError(413, 'payload_too_large', 'Enrollment payload is too large.')
  }

  const contentType = request.headers.get('content-type')?.toLowerCase() ?? ''
  if (contentType.includes('application/json')) return JSON.parse(body)
  if (contentType.includes('application/x-www-form-urlencoded')) {
    return Object.fromEntries(new URLSearchParams(body))
  }
  throw new EnrollmentError(
    415,
    'unsupported_media_type',
    'Use application/json or application/x-www-form-urlencoded.',
  )
}

async function post({ request }: { request: Request }) {
  const authorization = request.headers.get('authorization') ?? ''
  const match = authorization.match(/^Bearer\s+(.+)$/i)
  if (!match) return json({ error: 'missing_token' }, 401)

  try {
    const input = EnrollmentRegistrationSchema.parse(await parseInput(request))
    const result = await registerEnrolledDevice(db, match[1].trim(), input)
    return json({ ok: true, ...result }, result.created ? 201 : 200)
  } catch (error) {
    if (error instanceof EnrollmentError) {
      return json({ error: error.code, message: error.message }, error.status)
    }
    if (error instanceof SyntaxError) {
      return json({ error: 'invalid_json', message: 'Invalid JSON payload.' }, 400)
    }
    if (error && typeof error === 'object' && 'issues' in error) {
      return json({ error: 'invalid_payload', message: 'Invalid enrollment payload.' }, 400)
    }
    console.error('Device enrollment failed:', error)
    return json({ error: 'enrollment_failed' }, 500)
  }
}

export const Route = createFileRoute('/api/enroll')({
  server: {
    handlers: {
      POST: post,
    },
  },
})

