.tv-table tbody tr[data-selected="true"] { background: var(--bg-active); }
.tv-table tbody tr:last-child td { border-bottom: none; }

/* ---------- Dialog ---------------------------------------- */
.tv-dialog-overlay {
  position: fixed; inset: 0; z-index: 50;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(2px);
  display: flex; align-items: center; justify-content: center;
}
.tv-dialog {
  position: relative;
  width: 100%;
  max-width: 384px;
  display: grid;
  gap: 16px;
  padding: 16px;
  border-radius: var(--radius-sm);
  background: var(--bg-panel);
  color: var(--fg-1);
  font-size: var(--text-xs);
  line-height: var(--leading-relaxed);
  box-shadow: var(--sh-pop), var(--ring-card);
}
.tv-dialog__header { display: flex; flex-direction: column; gap: 4px; }
.tv-dialog__title { font-size: var(--text-card-title); font-weight: var(--weight-medium); }
.tv-dialog__description { font-size: var(--text-xs); color: var(--fg-3); line-height: var(--leading-relaxed); }
.tv-dialog__footer { display: flex; justify-content: flex-end; gap: 8px; }

/* ---------- Badge (ticket status) ------------------------- */
.tv-badge--secondary { background: var(--bg-sunken); color: var(--fg-2); }

/* ---------- SideNavItem ----------------------------------- */
.tv-navitem {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 28px;
  padding: 0 14px;
  border: none;
  background: transparent;
  text-align: left;
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 500;
  color: var(--fg-3);
  cursor: pointer;
  transition: 0.1s;
}
.tv-seg > button[data-active="true"] {
  background: var(--bg-panel);
  color: var(--fg-1);
  box-shadow: var(--sh-sm);
}

.tv-row-click { cursor: pointer; }

/* Radix renders Dialog.Overlay and Dialog.Content as portal siblings, so the
   dialog can't be centered by the overlay (as the source markup did). Make the
   dialog self-center as a fixed element and sit above the overlay. */
.tv-dialog {
  position: fixed;
  inset: 0;
  margin: auto;
  height: max-content;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  z-index: 51;
  animation: tvDialogIn 0.14s ease;
}
@keyframes tvDialogIn {
  from { transform: translateY(6px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* App rail icon buttons */
.tv-rail-ico {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
import { betterAuth } from 'better-auth'
import { APIError } from 'better-auth/api'
import { tanstackStartCookies } from 'better-auth/tanstack-start'
import { drizzleAdapter } from 'better-auth/adapters/drizzle'
import { and, eq, isNull } from 'drizzle-orm'

import { db } from '#/db'
import { account, invitation, session, user, verification } from '#/db/schema'
import { invitedRegistration } from '#/lib/registration-context'

/**
 * Registration policy: invite-only, with a bootstrap exception for the very
 * first account. The public sign-up route stays reachable, but this hook
 * rejects any sign-up that is neither the first user nor backed by a valid,
 * unexpired invitation for that email address. `role` is server-assigned and
 * never accepted from client input.
 */
export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: 'pg',
    schema: { user, session, account, verification },
  }),
  // Only accept auth requests from the configured public origin. Secure cookies
  // are derived automatically from an https BETTER_AUTH_URL.
  trustedOrigins: process.env.BETTER_AUTH_URL
    ? [process.env.BETTER_AUTH_URL]
    : [],
  // Throttle credential endpoints (active in production). Memory-backed, which
  // is sufficient for a single-container deployment.
  rateLimit: {
    window: 60,
    max: 100,
    customRules: {
      '/sign-in/email': { window: 60, max: 10 },
      '/sign-up/email': { window: 60, max: 5 },
    },
  },
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 10,
  },
  user: {
    additionalFields: {
      role: {
        type: 'string',
        required: false,
        defaultValue: 'member',
        input: false,
      },
    },
  },
  databaseHooks: {
    user: {
      create: {
        before: async (newUser) => {
          const email = newUser.email.toLowerCase()

          const [firstUser] = await db
            .select({ id: user.id })
            .from(user)
            .limit(1)

          // Bootstrap: the first account ever created becomes the admin.
          if (!firstUser) {
            return { data: { ...newUser, email, role: 'admin' } }
          }

          // Otherwise the sign-up must originate from acceptInvite, which only
          // enters this context after validating the invite TOKEN. The public
          // sign-up route never sets it, so a known email alone is rejected.
          const invited = invitedRegistration.getStore()
          if (invited && invited.email === email) {
            return { data: { ...newUser, email, role: invited.role } }
          }

          throw new APIError('FORBIDDEN', {
            message:
              'Registration is invite-only. Ask an administrator for an invitation.',
          })
        },
        after: async (createdUser) => {
          // Consume any pending invitations for this email.
          await db
            .update(invitation)
            .set({ acceptedAt: new Date() })
            .where(
              and(
                eq(invitation.email, createdUser.email.toLowerCase()),
                isNull(invitation.acceptedAt),
              ),
            )
        },
      },
    },
  },
  plugins: [tanstackStartCookies()],
})

export type Session = typeof auth.$Infer.Session

